"use strict";const REGION_MAP=new Map([["PRN",{code:"PRN",name:"Pacific Northwest Region",location:"Khu vực Tây Bắc Thái Bình Dương"}],["VLL",{code:"VLL",name:"Valley Region",location:"Valley"}],["ASH",{code:"ASH",name:"Ashburn Region",location:"Ashburn"}],["DFW",{code:"DFW",name:"Dallas/Fort Worth Region",location:"Dallas/Fort Worth"}],["LLA",{code:"LLA",name:"Los Angeles Region",location:"Los Angeles"}],["FRA",{code:"FRA",name:"Frankfurt",location:"Frankfurt"}],["SIN",{code:"SIN",name:"Singapore",location:"Singapore"}],["NRT",{code:"NRT",name:"Tokyo",location:"Japan"}],["HKG",{code:"HKG",name:"Hong Kong",location:"Hong Kong"}],["SYD",{code:"SYD",name:"Sydney",location:"Sydney"}],["PNB",{code:"PNB",name:"Pacific Northwest - Beta",location:"Pacific Northwest"}]]);function parseRegion(html){try{const match1=html.match(/"endpoint":"([^"]+)"/);const match2=match1?null:html.match(/endpoint\\":\\"([^\\"]+)\\"/);const rawEndpoint=match1&&match1[1]||match2&&match2[1];if(!rawEndpoint){return"PRN"}const endpoint=rawEndpoint.replace(/\\\//g,"/");try{const url=new URL(endpoint);const regionParam=url.searchParams?url.searchParams.get("region"):null;if(regionParam){const regionCode=regionParam.toUpperCase();if(REGION_MAP.has(regionCode)){return regionCode}}}catch(urlError){}return"PRN"}catch(error){return"PRN"}}async function genTotp(secret){try{const cleaned=String(secret||"").replace(/\s+/g,"").toUpperCase();if(!cleaned){throw new Error("TOTP secret is empty")}const crypto=require("crypto");function base32Decode(base32){const alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";let bits="";for(let i=0;i<base32.length;i++){const val=alphabet.indexOf(base32.charAt(i).toUpperCase());if(val===-1)continue;bits+=val.toString(2).padStart(5,"0")}const bytes=[];for(let i=0;i+8<=bits.length;i+=8){bytes.push(parseInt(bits.slice(i,i+8),2))}return Buffer.from(bytes)}const key=base32Decode(cleaned);const counter=Math.floor(Date.now()/3e4);const buffer=Buffer.alloc(8);buffer.writeBigUInt64BE(BigInt(counter));const digest=crypto.createHmac("sha1",key).update(buffer).digest();const offset=digest[digest.length-1]&15;const code=((digest[offset]&127)<<24|(digest[offset+1]&255)<<16|(digest[offset+2]&255)<<8|digest[offset+3]&255)%1e6;return code.toString().padStart(6,"0")}catch(error){throw new Error(`Failed to generate TOTP code: ${error.message}`)}}function getRegionInfo(code){return REGION_MAP.get(code.toUpperCase())||null}function getAllRegions(){return Array.from(REGION_MAP.values())}function createAuthCore(opts={}){return{parseRegion:parseRegion,genTotp:genTotp,getRegionInfo:getRegionInfo,getAllRegions:getAllRegions,REGION_MAP:REGION_MAP}}module.exports={REGION_MAP:REGION_MAP,parseRegion:parseRegion,genTotp:genTotp,getRegionInfo:getRegionInfo,getAllRegions:getAllRegions,createAuthCore:createAuthCore};
